#!/usr/bin/env python3
from __future__ import annotations
import json, os, time, urllib.request, urllib.parse
BASE="https://prove2.me/api/v1"
NAME="CookPvsNP_comp_machine"
DEFINITION="import Definitions.Def_CookPvsNP_defs\n\nset_option autoImplicit false\n\nnamespace CookPvsNP\n\nstructure CompCell (Γ₁ Γ₂ : Type) where\n  one : Option Γ₁\n  two : Option Γ₂\n  setupOrigin : Bool\n  leftB : Bool\n  rightB : Bool\n  secondOrigin : Bool\n  finalOrigin : Bool\nderiving DecidableEq\n\nnoncomputable instance instFintypeCompCell {Γ₁ Γ₂ : Type} [Fintype Γ₁] [Fintype Γ₂] :\n    Fintype (CompCell Γ₁ Γ₂) :=\n  Fintype.ofInjective\n    (fun c : CompCell Γ₁ Γ₂ =>\n      (c.one, c.two, c.setupOrigin, c.leftB, c.rightB, c.secondOrigin, c.finalOrigin))\n    (by\n      intro a b h\n      cases a\n      cases b\n      simp_all)\n\ndef CompCell.blank {Γ₁ Γ₂ : Type} : CompCell Γ₁ Γ₂ :=\n  ⟨none, none, false, false, false, false, false⟩\n\ndef CompCell.unpack {Γ₁ Γ₂ : Type} : Option (CompCell Γ₁ Γ₂) → CompCell Γ₁ Γ₂\n  | none => .blank\n  | some c => c\n\ndef CompCell.pack {Γ₁ Γ₂ : Type} (c : CompCell Γ₁ Γ₂) : Option (CompCell Γ₁ Γ₂) :=\n  if c.one = none ∧ c.two = none ∧ !c.setupOrigin ∧ !c.leftB ∧ !c.rightB ∧\n      !c.secondOrigin ∧ !c.finalOrigin then none else some c\n\ndef compInputEmbedding {Sym₁ Γ₁ Γ₂ : Type} (ι : Sym₁ ↪ Γ₁) :\n    Sym₁ ↪ CompCell Γ₁ Γ₂ where\n  toFun x := ⟨some (ι x), none, false, false, false, false, false⟩\n  inj' := by\n    intro a b h\n    apply ι.injective\n    exact Option.some.inj (congrArg CompCell.one h)\n\ndef compOutputEmbedding {Sym₃ Γ₁ Γ₂ : Type} (ι : Sym₃ ↪ Γ₂) :\n    Sym₃ ↪ CompCell Γ₁ Γ₂ where\n  toFun x := ⟨none, some (ι x), false, false, false, false, false⟩\n  inj' := by\n    intro a b h\n    apply ι.injective\n    exact Option.some.inj (congrArg CompCell.two h)\n\nnoncomputable def translateCell {Sym₂ Γ₁ Γ₂ : Type}\n    (ι₁ : Sym₂ ↪ Γ₁) (ι₂ : Sym₂ ↪ Γ₂) (a : Γ₁) : Option Γ₂ := by\n  classical\n  exact if h : ∃ s : Sym₂, ι₁ s = a then some (ι₂ (Classical.choose h)) else none\n\ninductive CompQ (Q₁ Q₂ : Type)\n  | setupStart\n  | setupScan\n  | setupReturn\n  | setupBounce\n  | sim₁ (q : Q₁)\n  | sim₁R (q : Q₁)\n  | sim₁RBack (q : Q₁) (expand : Bool)\n  | sim₁L (q : Q₁)\n  | sim₁LBack (q : Q₁)\n  | convPlaceLeft\n  | convCopy (first : Bool)\n  | convEmptyRight\n  | convSeekOldRight\n  | convReturn\n  | convBounce\n  | sim₂ (q : Q₂)\n  | sim₂R (q : Q₂)\n  | sim₂RBack (q : Q₂) (expand : Bool)\n  | sim₂L (q : Q₂)\n  | sim₂LBack (q : Q₂) (expand : Bool)\n  | finalClean (ended : Bool)\n  | finalReturn\n  | finalBounce\n  | haltAccept\n  | haltReject\nderiving DecidableEq, Fintype\n\nnoncomputable def compTM\n    {Sym₂ Γ₁ Γ₂ : Type} [Fintype Γ₁] [Fintype Γ₂]\n    (ι₂₁ : Sym₂ ↪ Γ₁) (ι₂₂ : Sym₂ ↪ Γ₂)\n    (M₁ : TM Γ₁) (M₂ : TM Γ₂) : TM (CompCell Γ₁ Γ₂) where\n  Q := CompQ M₁.Q M₂.Q\n  q₀ := .setupStart\n  qaccept := .haltAccept\n  qreject := .haltReject\n  accept_ne_reject := by intro h; cases h\n  δ := fun q s =>\n    let c := CompCell.unpack s\n    let keep := CompCell.pack c\n    match q with\n    | .setupStart =>\n        (.setupScan, CompCell.pack { c with setupOrigin := true }, .right)\n    | .setupScan =>\n        match s with\n        | none =>\n            (.setupReturn, CompCell.pack { c with rightB := true }, .left)\n        | some _ => (.setupScan, keep, .right)\n    | .setupReturn =>\n        if c.setupOrigin then\n          (.setupBounce, CompCell.pack { c with setupOrigin := false }, .right)\n        else\n          (.setupReturn, keep, .left)\n    | .setupBounce =>\n        (.sim₁ M₁.q₀, keep, .left)\n    | .sim₁ q₁ =>\n        if q₁ = M₁.qaccept ∨ q₁ = M₁.qreject then\n          (.convPlaceLeft, CompCell.pack { c with secondOrigin := true }, .left)\n        else\n          match M₁.δ q₁ c.one with\n          | (q', w, .right) =>\n              (.sim₁R q', CompCell.pack { c with one := w }, .right)\n          | (q', w, .left) =>\n              (.sim₁L q', CompCell.pack { c with one := w }, .left)\n    | .sim₁R q₁ =>\n        if c.rightB then\n          (.sim₁RBack q₁ true, CompCell.pack { c with rightB := false }, .right)\n        else\n          (.sim₁RBack q₁ false, keep, .left)\n    | .sim₁RBack q₁ expand =>\n        if expand then\n          (.sim₁ q₁, CompCell.pack { c with rightB := true }, .left)\n        else\n          (.sim₁ q₁, keep, .right)\n    | .sim₁L q₁ =>\n        (.sim₁LBack q₁, keep, .right)\n    | .sim₁LBack q₁ =>\n        (.sim₁ q₁, keep, .left)\n    | .convPlaceLeft =>\n        (.convCopy true, CompCell.pack { c with leftB := true }, .right)\n    | .convCopy first =>\n        match c.one with\n        | some a =>\n            (.convCopy false,\n              CompCell.pack { c with two := translateCell ι₂₁ ι₂₂ a },\n              .right)\n        | none =>\n            if first then\n              (.convEmptyRight, keep, .right)\n            else if c.rightB then\n              (.convReturn, keep, .left)\n            else\n              (.convSeekOldRight, CompCell.pack { c with rightB := true }, .right)\n    | .convEmptyRight =>\n        if c.rightB then\n          (.convReturn, keep, .left)\n        else\n          (.convSeekOldRight, CompCell.pack { c with rightB := true }, .right)\n    | .convSeekOldRight =>\n        if c.rightB then\n          (.convReturn, CompCell.pack { c with rightB := false }, .left)\n        else\n          (.convSeekOldRight, CompCell.pack { c with one := none, two := none }, .right)\n    | .convReturn =>\n        if c.secondOrigin then\n          (.convBounce, CompCell.pack { c with secondOrigin := false }, .right)\n        else\n          (.convReturn, keep, .left)\n    | .convBounce =>\n        (.sim₂ M₂.q₀, keep, .left)\n    | .sim₂ q₂ =>\n        if q₂ = M₂.qaccept ∨ q₂ = M₂.qreject then\n          let ended := c.two.isNone\n          let c' : CompCell Γ₁ Γ₂ :=\n            { c with\n              one := none\n              setupOrigin := false\n              secondOrigin := false\n              finalOrigin := true }\n          (.finalClean ended, CompCell.pack c', .right)\n        else\n          match M₂.δ q₂ c.two with\n          | (q', w, .right) =>\n              (.sim₂R q', CompCell.pack { c with two := w }, .right)\n          | (q', w, .left) =>\n              (.sim₂L q', CompCell.pack { c with two := w }, .left)\n    | .sim₂R q₂ =>\n        if c.rightB then\n          (.sim₂RBack q₂ true, CompCell.pack { c with rightB := false }, .right)\n        else\n          (.sim₂RBack q₂ false, keep, .left)\n    | .sim₂RBack q₂ expand =>\n        if expand then\n          (.sim₂ q₂, CompCell.pack { c with rightB := true }, .left)\n        else\n          (.sim₂ q₂, keep, .right)\n    | .sim₂L q₂ =>\n        if c.leftB then\n          (.sim₂LBack q₂ true, CompCell.pack { c with leftB := false }, .left)\n        else\n          (.sim₂LBack q₂ false, keep, .right)\n    | .sim₂LBack q₂ expand =>\n        if expand then\n          (.sim₂ q₂, CompCell.pack { c with leftB := true }, .right)\n        else\n          (.sim₂ q₂, keep, .left)\n    | .finalClean ended =>\n        if c.rightB then\n          (.finalReturn, none, .left)\n        else if ended then\n          (.finalClean true, none, .right)\n        else\n          match c.two with\n          | none => (.finalClean true, none, .right)\n          | some _ =>\n              (.finalClean false,\n                CompCell.pack { c with\n                  one := none\n                  setupOrigin := false\n                  leftB := false\n                  rightB := false\n                  secondOrigin := false\n                  finalOrigin := false },\n                .right)\n    | .finalReturn =>\n        if c.finalOrigin then\n          (.finalBounce, CompCell.pack { c with finalOrigin := false }, .right)\n        else\n          (.finalReturn, keep, .left)\n    | .finalBounce =>\n        (.haltAccept, keep, .left)\n    | .haltAccept => (.haltAccept, keep, .right)\n    | .haltReject => (.haltReject, keep, .right)\n\nend CookPvsNP\n"

def api(method,path,token=None,payload=None):
    h={"Accept":"application/json"}; data=None
    if token: h["Authorization"]=f"Bearer {token}"
    if payload is not None:
        h["Content-Type"]="application/json"; data=json.dumps(payload).encode()
    req=urllib.request.Request(BASE+path,data=data,headers=h,method=method)
    with urllib.request.urlopen(req,timeout=60) as r:
        raw=r.read().decode(); return json.loads(raw) if raw else {}

def main():
    key=os.environ["PROVE2ME_API_KEY"].strip()
    token=api("POST","/agent/refresh",payload={"api_key":key})["access_token"]
    q=api("GET","/theorems?"+urllib.parse.urlencode({"q":NAME,"limit":"20","offset":"0"}),token)
    hit=next((t for t in q.get("theorems",[]) if t.get("definition_name")==NAME or t.get("theorem_name")==NAME),None)
    if hit:
        print("EXISTS",json.dumps(hit)); return
    pub=api("POST","/submit-definition",token,payload={
      "definition_name":NAME,
      "definition_title":"Composite Cook one-tape transducer with two-track work alphabet",
      "definition":DEFINITION,
      "natural_language_statement":"A concrete finite-alphabet one-tape machine construction for sequentially composing two Cook-style polynomial-time transducers. The combined tape stores the first and second machine alphabets on separate tracks, uses movable boundary markers to preserve the finite-list tape semantics, translates the intermediate output between the two symbol embeddings, and cleans the final tape into the requested output encoding.",
      "source":"Cook, The P versus NP problem, Clay Mathematics Institute (2000), Definition 3; standard sequential simulation of one-tape deterministic transducers.",
      "tags":["complexity-theory","turing-machines","polynomial-time","composition"]})
    print("QUEUED",json.dumps(pub))
    jid=pub.get("job_id") or pub["jobs"][0]["job_id"]
    for _ in range(180):
        time.sleep(5)
        st=api("GET",f"/publish-jobs/{jid}",token)
        print("STATUS",st.get("status"),st.get("theorem_id") or st.get("definition_id"),st.get("error_message",""))
        if st.get("status") in {"PUBLISHED","FAILED","ERROR"}:
            print("FINAL",json.dumps(st)); return
if __name__=="__main__": main()
